// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(c) && actor != address(this) && actor != c.owner());
        amount = bound(amount, 1, 100 ether);
        vm.deal(address(c), amount);
        vm.deal(actor, 1 ether);

        bool ok;
        vm.prank(actor);
        try c.sendMoney(actor, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
